// Builds count leads (default 5, max 50): Meta and website alternately, last one repeats a website family.
const q = $input.first().json.query || {};
const count = Math.min(Math.max(parseInt(q.count, 10) || 5, 2), 50);
const base = ($env.PUBLIC_BASE_URL || 'http://localhost:5678').replace(/\/+$/, '');
const page = '100000000000001';
const rnd = (n) => Math.floor(Math.random() * n);
const pick = (a) => a[rnd(a.length)];
const out = [];
let lastWeb = null;
for (let i = 0; i < count; i++) {
  const now = Math.floor(Date.now() / 1000);
  if (i === count - 1 && lastWeb) {
    const again = { ...lastWeb, message: 'Following up on my earlier message.', submission_id: 'demo-' + Date.now() + '-' + i };
    out.push({ json: { kind: 'web, same family again', url: base + '/webhook/leadops/web-form', body: JSON.stringify(again), event_key: 'sid:' + again.submission_id } });
  } else if (i % 2 === 0) {
    // 17 digits, unquoted, like real Meta ids (larger than JavaScript's safe integers)
    const leadgen = '9' + String(Date.now()).slice(-11) + String(i).padStart(2, '0') + String(rnd(1000)).padStart(3, '0');
    const body = '{"object":"page","entry":[{"id":"' + page + '","time":' + now + ',"changes":[{"field":"leadgen","value":'
      + '{"leadgen_id":' + leadgen + ',"page_id":"' + page + '","form_id":"200000000000001","ad_id":"300000000000003","created_time":' + now + '}}]}]}';
    out.push({ json: { kind: 'meta', url: base + '/webhook/leadops/meta', body, event_key: leadgen } });
  } else {
    const ar = rnd(2) === 0;
    lastWeb = {
      name: ar ? pick(['نور حسن', 'سارة الكعبي', 'محمد الزعابي', 'هند السويدي']) : pick(['Anna Kowalski', 'Ravi Menon', 'Chloe Martin', 'Tom Baker']),
      phone: '+97155' + String(rnd(1e7)).padStart(7, '0'),
      email: 'family' + String(rnd(1e6)).padStart(6, '0') + '@example.com',
      message: ar ? 'نرغب في معرفة الرسوم الدراسية والمقاعد المتاحة.' : 'We are relocating in January. Is there space in Year 1?',
      grade: pick(['FS2', 'Year 1', 'Year 4', 'Year 9']),
      utm_source: pick(['google', 'instagram', 'newsletter']), utm_medium: 'cpc',
      utm_campaign: pick(['Brand search - admissions', 'Open day October', 'Fees and scholarships']),
      page_url: 'https://school.example/admissions', submission_id: 'demo-' + Date.now() + '-' + i,
    };
    out.push({ json: { kind: 'web', url: base + '/webhook/leadops/web-form', body: JSON.stringify(lastWeb), event_key: 'sid:' + lastWeb.submission_id } });
  }
}
return out;

const sent = $('Make demo leads').all();
return [{ json: {
  sent: $input.all().map((r, i) => ({ kind: sent[i].json.kind, http: r.json.statusCode, reply: r.json.body ?? r.json.data })),
  keys: sent.map((s) => s.json.event_key),
} }];

// Readable page: what happened to each lead, and where each step shows up in n8n.
const base = ($env.PUBLIC_BASE_URL || 'http://localhost:5678').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const rows = $input.all().map((r) => r.json).filter((r) => r.source);
const sent = $('Summary').first().json.sent.length;
const ex = (id, label, what) => '<li><a href="' + base + '/workflow/' + id + '/executions" target="_blank">' + label + '</a>: ' + what + '</li>';
const tr = rows.map((r, n) => {
  const result = !r.inquiry_id ? '<span class="bad">' + esc(r.inbox_status) + (r.error ? ': ' + esc(r.error) : '') + '</span>'
    : r.status === 'merged' ? 'Merged into #' + r.duplicate_of + ' (same family)' : 'New inquiry #' + r.inquiry_id;
  const tg = r.status === 'merged' ? 'no (merged, by design)' : r.notified ? 'sent' : '<span class="bad">not yet</span>';
  const page = r.public_token ? '<a href="' + base + '/webhook/leadops/lead?t=' + r.public_token + '&u=' + encodeURIComponent(r.agent_code || '') + '" target="_blank">Open</a>' : '';
  return '<tr><td>' + (n + 1) + '</td><td>' + (r.source === 'meta' ? 'Meta lead ad' : 'Website form') + '</td>'
    + '<td><bdi>' + esc(r.full_name) + '</bdi><div class="dim" dir="ltr">' + esc(r.phone_e164) + ' · ' + esc(String(r.language || '').toUpperCase()) + '</div></td>'
    + '<td>' + esc(r.campaign_name) + '</td><td>' + result + '</td><td>' + (r.crm_record_id ? esc(r.crm_record_id) : '-') + '</td>'
    + '<td>' + esc(r.agent_name || '-') + '</td><td>' + tg + '</td><td>' + page + '</td></tr>';
}).join('');
const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Demo leads sent</title><style>'
  + 'body{font:15px/1.5 system-ui,sans-serif;margin:24px auto;max-width:1100px;padding:0 16px;background:#fff;color:#1d1d1f}'
  + '@media(prefers-color-scheme:dark){body{background:#1a1a1a;color:#eee}th{background:#262626!important}td,th{border-color:#333!important}a{color:#8ab4ff}}'
  + 'table{border-collapse:collapse;width:100%;margin:12px 0 24px}th,td{border-bottom:1px solid #e5e5e5;padding:8px;text-align:left;vertical-align:top}'
  + 'th{background:#f5f5f5;font-weight:600}.dim{opacity:.65;font-size:13px}.bad{color:#d33}li{margin:4px 0}.wrap{overflow-x:auto}'
  + '</style></head><body>'
  + '<h1>Sent ' + sent + ' demo leads</h1><p>They went through the real intake webhooks, just like leads from Meta and the website. Here is what happened to each one:</p>'
  + '<div class="wrap"><table><tr><th>#</th><th>Came from</th><th>Family</th><th>Campaign</th><th>Result</th><th>CRM contact</th><th>Assigned to</th><th>Telegram</th><th>Lead page</th></tr>'
  + (tr || '<tr><td colspan="9">Nothing found yet. Refresh the dashboard in a moment.</td></tr>') + '</table></div>'
  + '<h2>Where each step shows up in n8n</h2><p class="dim">Each link opens that workflow\'s Executions list. Click the newest run, then click any node to see what went in and out.</p><ol>'
  + ex('lo91DemoLeads000', '91 Demo lead generator', 'this run. "Post to intake webhook" shows every request and reply')
  + ex('lo01MetaIntake00', '01 Meta intake', 'checked the signature and saved the Meta leads')
  + ex('lo02WebIntake000', '02 Website form intake', 'checked and saved the website leads')
  + ex('lo03Processor000', '03 Lead processor', 'cleaned the data, merged repeats, picked the agent')
  + ex('lo04CrmSync00000', '04 CRM sync', 'created the contact and note in the CRM')
  + ex('lo05Notify000000', '05 Notify agent', 'wrote the Telegram message')
  + ex('lo90MockApis0000', '90 Mock providers', 'where the Telegram messages "arrive". Open "Telegram sendMessage" to read them')
  + '</ol><p><a href="' + base + '/webhook/leadops/dashboard" target="_blank">Open the dashboard</a> (user admissions, password in .env) · <a href="?count=5">Send 5 more</a></p>'
  + '<p class="dim">Leads nobody claims get a reminder after 5 minutes and go to the manager after 10. Claim one from its lead page to stop that.</p></body></html>';
return [{ json: { html } }];
